// The unconfigured-source classification (tmdb-enrichment D3): a DORMANT
// source — required secrets resolving against no module binding — answers the
// interactive endpoints 503 unavailable with the missing-config reason, never
// 502 upstream_error (that code means the upstream itself failed). The tests
// replay the cmd closure's post-translation error shape — the sentinel %w-
// wrapped with the plugin context, exactly what newSearchClosure/
// newIdentifyClosure hand the handler on the live path — so classification
// through errors.Is is what is pinned, not a bare ==.

// TestSourceSearchUnconfiguredAnswers503 pins GET
// /admin/sources/{plugin_id}/search's dormant-source answer: 503 with the
// canonical unavailable code, retry disabled (the nil-closure 503 shape), the
// reason carrying the missing-config meaning, and the closure consulted
// exactly once (the classification happens after the queue's pre-action
// check, not before it).
func TestSourceSearchUnconfiguredAnswers503(t *testing.T) {
	st := openAPIStore(t)
	var calls []searchCall
	deps := Deps{
		AdminToken: adminToken,
		Store:      st,
		SearchSource: fakeSearch(nil,
			fmt.Errorf("search %q: %w", "tmdb", ErrUnconfiguredSource), &calls),
	}
	h := New(deps)

	resp := doRequest(t, h, http.MethodGet,
		"/api/v1/admin/sources/tmdb/search?query=aria", "", adminToken)
	defer resp.Body.Close()
	if resp.StatusCode != http.StatusServiceUnavailable {
		t.Fatalf("status = %d, want %d", resp.StatusCode, http.StatusServiceUnavailable)
	}
	eb := decodeError(t, resp)
	if eb.Error.Code != "unavailable" {
		t.Fatalf("error code = %q, want %q", eb.Error.Code, "unavailable")
	}
	if eb.Error.Retryable {
		t.Fatal("the unavailable answer must carry retry disabled")
	}
	if !strings.Contains(eb.Error.Message, "unconfigured") || !strings.Contains(eb.Error.Message, "secrets") {
		t.Fatalf("message = %q, want the missing-config reason", eb.Error.Message)
	}
	if len(calls) != 1 {
		t.Fatalf("SearchSource calls = %d, want 1", len(calls))
	}
}

